window.QUIZ_QUESTIONS=[[{"id": "Q1-01", "topic": "M4", "type": "multi", "stem": "A warehouse robot can move horizontally and vertically. In one operating mode it performs the two movements sequentially; in another it performs them simultaneously. For a destination requiring 6 and 8 seconds on the two axes, which statements correctly connect the distance measure to the task?", "options": ["Euclidean distance is always the right measure because the floor is two-dimensional", "Sequential travel takes 14 seconds and is represented by L1 on these time coordinates", "Simultaneous travel takes 8 seconds and is represented by L-infinity on these time coordinates", "Switching movement rules can change which station is nearest in operational travel time"]}, {"id": "Q1-02", "topic": "M3", "type": "multi", "stem": "Which activities belong to model selection and must avoid using the final test outcomes?", "options": ["Computing the locked model's final test score", "Choosing k for k-NN", "Choosing an SVM kernel", "Choosing a classification threshold"]}, {"id": "Q1-03", "topic": "M2", "type": "multi", "stem": "A quality team tunes a soft-margin SVM using the stated objective total classification-loss penalty + lambda times squared coefficient norm. It raises lambda, and training fit becomes worse. Which interpretations are justified?", "options": ["A larger lambda in this stated objective has to eliminate all training errors", "Validation is needed to judge whether the tradeoff improves generalization", "The deterioration in training fit alone proves the new setting is worse for deployment", "The change places more emphasis on the coefficient penalty"]}, {"id": "Q1-04", "topic": "M10", "type": "single", "stem": "A repair-time tree sends a new machine into a leaf containing training repair times 10, 14, and 18 hours. The manager claims the tree must predict exactly 14 hours and guarantee that the next repair will take 14 hours. What is the best correction?", "options": ["The tree must fit three separate slope coefficients in this leaf", "The leaf predicts the most frequent machine label instead of hours", "A tree cannot make numeric-response predictions", "An ordinary regression leaf predicts 14 hours, but the prediction is not a guarantee for an individual repair"]}, {"id": "Q1-05", "topic": "M4", "type": "multi", "stem": "A city needs different daytime and nighttime patrol locations. Which changes are analytically reasonable?", "options": ["Check patrol coverage and budgets for each period", "Keep the original pooled clustering solely because it has more records", "Cluster nighttime incidents separately", "Cluster daytime incidents separately"]}, {"id": "Q1-06", "topic": "M6", "type": "single", "stem": "An engineer wants an alarm for a sustained increase in axle temperature rather than a future price forecast. Which lecture method directly serves this purpose?", "options": ["Poisson regression", "CUSUM", "PCA", "k-means"]}, {"id": "Q1-07", "topic": "M10", "type": "multi", "stem": "A lender needs a probability that a borrower defaults and then a yes/no intervention rule. Historical default outcomes are coded 1 and 0; borrower attributes are available before lending. Which statements are appropriate?", "options": ["An SVM class score is automatically a probability between zero and one", "Logistic regression directly models a binary-event probability from attributes", "The intervention threshold should reflect the costs of missed defaults and unnecessary interventions", "A threshold can turn the estimated probability into a class or intervention decision"]}, {"id": "Q1-08", "topic": "M7", "type": "multi", "stem": "Which statements about single exponential smoothing are correct for 0<alpha<1?", "options": ["Recent observations receive larger weights than distant ones", "It explicitly models a seasonal cycle by itself", "Older observations remain represented in the previous level", "A larger alpha follows new observations more quickly"]}, {"id": "Q1-09", "topic": "M2", "type": "multi", "stem": "A plant compares a linear SVM with a classification tree. The SVM uses the rule x1>5, independent of x2. The tree also splits on x2 and reduces training errors from 12 to 11 by isolating one training observation. No held-out results are available. Which conclusions follow?", "options": ["The isolated observation raises an overfitting concern", "Using an extra predictor establishes that the tree will generalize better", "The tree is proven superior because it makes one fewer training error", "x2 does not affect predictions under the stated SVM rule"]}, {"id": "Q1-10", "topic": "M2", "type": "single", "stem": "A diagram has x1 on the horizontal axis and x2 on the vertical axis. A classifier predicts rejection to the right of the vertical line x1=4. A rejected observation moves upward without changing x1. Which interpretation is defensible?", "options": ["The rule proves that x2 is irrelevant to every possible classifier", "It remains rejected under this rule, although a different fitted model could still use x2", "The line is a threshold on x2 because it is vertical", "It becomes accepted because x2 increased"]}, {"id": "Q1-11", "topic": "M7", "type": "single", "stem": "A level-only exponential-smoothing forecast is 80 units. A single unusually high observation of 100 arrives; the update uses alpha=.25. Which set of conclusions is correct?", "options": ["The new level is 85; the update reacts partly to the new observation, and a single update does not prove a permanent shift", "The level becomes 85 and therefore all future actual observations must equal 85", "The new level is 20 because alpha multiplies the previous level only", "The new level is 100 because every new observation replaces the past"]}, {"id": "Q1-12", "topic": "M10", "type": "multi", "stem": "Two defect classifiers are evaluated on the same 1,000 representative cases. A has 3 missed defects and 10 false alarms; B has 1 missed defect and 30 false alarms. A miss costs $100, a false alarm costs $2, and correct decisions are free. Which statements are correct?", "options": ["A makes fewer total errors but has higher stated total error cost than B", "The preferred classifier can change if the stated error costs change", "A costs $320 on this evaluation set", "B costs $160 on this evaluation set"]}, {"id": "Q1-13", "topic": "M7", "type": "single", "stem": "A manufacturer records operating hours before failure once for each successive item. Batches contain exactly 120 items but take 5 to 7 calendar days. The question concerns patterns by position in each batch. Which setup fits the observation index?", "options": ["Use item position as the response because it defines the ordering", "Use operating hours before failure as x_t and 120 observations as the seasonal period", "Use 7 as the seasonal period because it is the longest calendar duration", "Use day within batch as x_t and 6 observations as the seasonal period"]}, {"id": "Q1-14", "topic": "M8", "type": "single", "stem": "A regression reports a positive temperature coefficient with a confidence interval entirely above zero. The data are observational, and temperature changes along with production speed. Which conclusion is strongest without additional causal evidence?", "options": ["The interval proves that the model includes every important predictor", "Production speed cannot matter because temperature is significant", "Temperature has a supported positive association under the fitted specification, but changing temperature alone is not proved to cause that response change", "Every temperature intervention must increase the response by exactly the coefficient"]}, {"id": "Q1-15", "topic": "M2", "type": "single", "stem": "A safety classifier deliberately accepts more training misclassifications to obtain a wider-margin solution. A colleague says an SVM must always prefer whichever classifier makes the fewest training errors. Which answer best reflects the lecture tradeoff?", "options": ["Any training misclassification makes the fitted SVM mathematically unusable", "SVM is designed to minimize training error with no regard to margin", "A wider margin guarantees zero deployment errors", "Soft-margin SVM balances fit and margin; the setting should be compared using validation and the relevant error consequences"]}, {"id": "Q1-16", "topic": "M1", "type": "multi", "stem": "An analyst says “we use regression,” then names predictors, then supplies fitted coefficients. Which statements about the word model are valid?", "options": ["It can mean a method family", "It always means only an algorithm", "It can mean a predictor specification", "It can mean a fitted equation"]}, {"id": "Q1-17", "topic": "M10", "type": "multi", "stem": "A screening model labels disease as positive. On 100 patients it yields TP=36, FN=4, FP=12, TN=48. A doctor asks both how often diseased patients are caught and how often a positive result is actually disease. Which statements answer those two questions?", "options": ["The fraction of diseased patients caught is 36/40", "The four missed diseased patients belong in the positive-prediction denominator", "Both questions use the same denominator because positive means diseased in every cell", "The fraction of positive predictions that are actual disease is 36/48"]}, {"id": "Q1-18", "topic": "M9", "type": "multi", "stem": "Which statements about ordinary PCA are correct?", "options": ["It uses predictors without response labels", "It produces orthogonal loading directions", "It ranks components by predictor variance", "Its first component must maximize classification accuracy"]}, {"id": "Q1-19", "topic": "M1", "type": "multi", "stem": "A hospital predicts tomorrow's arrivals, estimates waiting time under alternative staffing levels, and must choose a schedule subject to a staffing budget. Which statements correctly distinguish the steps?", "options": ["The final constrained staffing choice is prescriptive", "The objectives and staffing constraints matter beyond the arrival prediction", "Forecasting arrivals is a predictive input to the decision", "A model with the lowest forecasting error automatically selects the optimal feasible schedule"]}, {"id": "Q1-20", "topic": "M6", "type": "multi", "stem": "In upper CUSUM, which changes generally make the alarm less sensitive?", "options": ["Increase the threshold T", "Increase the allowance C", "Reduce both C and T", "Initialize every period's cumulative statistic to zero regardless of its value"]}, {"id": "Q1-21", "topic": "M9", "type": "multi", "stem": "A positive-valued cost response has a strongly skewed distribution and a regression shows increasing error spread at higher fitted values. A team proposes a Box-Cox transformation. Which statements are defensible at the lecture's level?", "options": ["The transformation guarantees a normal response and a correct regression specification", "Model diagnostics and validation still matter after the transformation", "The transformation can be considered to improve the suitability of the response for modeling", "Choosing the logarithmic member requires the response to be suitable for a log transformation"]}, {"id": "Q1-22", "topic": "M4", "type": "single", "stem": "Optimal WSS drops as k rises all the way to one cluster per distinct point. Why does selecting the smallest WSS alone fail?", "options": ["More clusters always cost less operationally", "WSS cannot be computed from centers", "It mechanically favors increasingly fine partitions", "WSS measures classification labels"]}, {"id": "Q1-23", "topic": "M8", "type": "single", "stem": "Two regression specifications are fit to the same response on the same observations. The more complex model has a better likelihood but a higher AIC. What is the best interpretation?", "options": ["Its gain in fit did not offset AIC's complexity penalty, so AIC favors the lower-score model", "AIC has established the causal effect of the added predictors", "Higher AIC is always preferred because it measures extra information learned", "Higher likelihood means the more complex model must have lower AIC"]}, {"id": "Q1-24", "topic": "M2", "type": "multi", "stem": "Income ranges in millions while a credit measure ranges in hundreds. Which preparations can make distances more comparable?", "options": ["Standardize each feature using training statistics", "Evaluate whether feature weights reflect the intended notion of similarity", "Multiply every income by 1,000 without justification", "Scale each feature using its training range"]}, {"id": "Q1-25", "topic": "M10", "type": "multi", "stem": "A large tree improves training accuracy by isolating one observation in a leaf. What conclusions are warranted?", "options": ["Validation or pruning can assess whether the split helps", "Using an extra feature necessarily makes the tree better", "That split is a warning sign for overfitting", "The training improvement alone does not prove better generalization"]}, {"id": "Q1-26", "topic": "M4", "type": "single", "stem": "A city is choosing emergency-response stations. Candidate A is closer to many incidents by straight-line distance but separated by a river; candidate B has a longer straight-line distance but a direct road route. Which conclusion best follows?", "options": ["Candidate A must be preferred because k-means always gives the operational optimum", "The coordinates cannot be used in any clustering analysis", "The distance used in the analysis should represent travel constraints; Euclidean closeness alone need not imply quicker response", "Candidate B must be preferred without measuring travel times"]}, {"id": "Q1-27", "topic": "M5", "type": "multi", "stem": "A single extreme production record is found. Which actions are justified before deciding whether to exclude it?", "options": ["Assess whether the intended model should cover that condition", "Delete it immediately because it reduces R-squared", "Investigate sensor or transcription problems", "Check whether an unusual real operating condition occurred"]}, {"id": "Q1-28", "topic": "M7", "type": "multi", "stem": "A financial team needs both tomorrow's expected return and how variable that return may be. Which statements distinguish the lecture methods?", "options": ["Mean and variance forecasts answer different planning questions", "GARCH addresses time-varying variance", "A GARCH variance forecast alone gives the signed expected return", "ARIMA can address a forecast of the series value"]}, {"id": "Q1-29", "topic": "M8", "type": "multi", "stem": "An additive wage regression gives an age coefficient of $500 per year while holding education and other included attributes fixed. Older employees in the data also tend to have more education. Which statements are supported?", "options": ["Adding an age-by-education interaction leaves the age effect independent of education", "The coefficient describes the fitted age association conditional on the included predictors", "It does not by itself prove that making an employee a year older causes a $500 wage increase", "It is necessarily the difference in average wages between every pair of employees one year apart"]}, {"id": "Q1-30", "topic": "M2", "type": "single", "stem": "A nearest-neighbor loan model treats ZIP code as a numeric coordinate. It concludes that ZIP codes 10001 and 10002 represent more similar borrowers than 10001 and 90210 solely because their numerical difference is smaller. What is the central modeling problem?", "options": ["Standardizing ZIP code necessarily makes the distance substantively meaningful", "A numeric-looking category identifier does not automatically define a meaningful distance", "Using ZIP code as a response instead will automatically solve the similarity problem", "Any five-digit value is quantitative by definition"]}, {"id": "Q1-31", "topic": "M8", "type": "multi", "stem": "Which regressions are linear in their fitted coefficients?", "options": ["log(y)=b0+b1*x", "y=b0+b1*x+b2*x squared", "y=b0+exp(b1*x)", "y=b0+b1*x1+b2*x1*x2"]}, {"id": "Q1-32", "topic": "M4", "type": "multi", "stem": "In one k-means iteration, a few remote customer locations are assigned to a cluster with a dense central group. Which statements describe the standard mean-center update and its interpretation?", "options": ["A centroid is necessarily a feasible service site because it is computed from real customer locations", "The remote locations can pull the center away from the dense group", "The updated center must equal one of the observed customer locations", "The new center is the mean of the currently assigned coordinates"]}, {"id": "Q1-33", "topic": "M3", "type": "single", "stem": "A retailer operating five days weekly assigns every second record to validation in a fixed five-record cycle. What is the central concern?", "options": ["Five-record cycles guarantee representative subsets", "The split may isolate a particular weekday", "Validation labels become quantitative", "The split necessarily duplicates records"]}, {"id": "Q1-34", "topic": "M10", "type": "single", "stem": "A team fits many trees that all tend to choose the same dominant predictor first and make similar mistakes. In the lecture's random-forest idea, why restrict which predictors a tree or split may consider?", "options": ["To eliminate the need for observed responses during training", "To prove that the excluded predictors have no relationship with the response", "To make every tree identical so averaging becomes exact", "To introduce diversity so the combined prediction can benefit from different strengths and weaknesses"]}, {"id": "Q1-35", "topic": "M5", "type": "single", "stem": "A temperature is normal in summer but extremely unusual for its recorded winter date. Which outlier type best describes it?", "options": ["Only a point outlier regardless of context", "Contextual", "A categorical response", "A principal component"]}, {"id": "Q1-36", "topic": "M7", "type": "multi", "stem": "Which interpretations of ARIMA(2,1,3) are correct?", "options": ["Two autoregressive lags are included", "Three lagged innovations are included", "The series is differenced once", "The method estimates three independent cluster centers"]}, {"id": "Q1-37", "topic": "M2", "type": "single", "stem": "A three-class k-NN rule sees five neighbors: red, red, blue, green, blue. What additional detail is needed to return a unique class?", "options": ["A tie-breaking rule", "The number of clusters", "An ARIMA differencing order", "A regression coefficient for every class"]}, {"id": "Q1-38", "topic": "M8", "type": "multi", "stem": "Which statements about a p-value of .01 for a coefficient are valid?", "options": ["It establishes that the effect is practically large", "It can indicate evidence against a zero-coefficient null", "It means a 1% probability that the coefficient equals zero", "It is computed assuming the tested null and statistical model"]}, {"id": "Q1-39", "topic": "M9", "type": "multi", "stem": "A team uses the first two principal components, which explain 90% of predictor variance, before fitting a classification model. Which statements are justified?", "options": ["The omitted low-variance direction might still contain useful class information", "The resulting predictive procedure should be validated rather than judged solely by explained predictor variance", "The retained components summarize 90% of the variation in the predictors under the fitted scaling", "The classifier must achieve 90% accuracy"]}, {"id": "Q1-40", "topic": "M4", "type": "multi", "stem": "Which statements describe standard Euclidean k-means correctly?", "options": ["It guarantees the globally best clustering from every start", "It uses no known response labels", "Multiple initializations can produce different final solutions", "It repeatedly assigns points and updates means"]}, {"id": "Q1-41", "topic": "M3", "type": "multi", "stem": "After CV chooses a model specification, which actions are appropriate?", "options": ["Evaluate the refitted model on reserved test data", "Refit the chosen specification on all non-test data", "Choose the fold with the luckiest validation score as the final model", "Average fold coefficients as the mandatory final model"]}, {"id": "Q1-42", "topic": "M6", "type": "single", "stem": "An upper CUSUM monitor has baseline 10, allowance 2, previous statistic 4, and new observation 15. Its rule alarms when the updated statistic is greater than 6. Which interpretation is correct?", "options": ["The observation alone proves that a new machine caused the shift", "An alarm means every later observation will exceed the baseline", "The statistic becomes 3 and confirms the process is stable", "The statistic becomes 7 and an alarm is triggered; the alarm supports investigation of an upward change but not a particular cause"]}, {"id": "Q1-43", "topic": "M7", "type": "single", "stem": "A multiplicative seasonal factor for early-batch parts is .8 and the response is operating hours before failure. What conclusion is supported?", "options": ["Early-batch parts last 80 extra hours", "There is no seasonal effect", "Workers' fatigue is proven to cause the pattern", "Early-batch parts have lower expected operating hours than the adjusted baseline"]}, {"id": "Q1-44", "topic": "M3", "type": "multi", "stem": "A team reserves 200 of 1,000 observations for a final test and uses four-fold validation on the other 800 to compare SVM settings. Which statements describe the fitting stages correctly?", "options": ["After selection, the chosen specification can be refit on all 800 non-test observations", "The final model should be whichever fold happened to score best", "The reserved 200 may be used to select lambda without affecting their independent-test role", "Each equal-sized fold fit uses 600 training observations and 200 validation observations"]}, {"id": "Q1-45", "topic": "M3", "type": "single", "stem": "Ten candidate models are fit on training data and the best validation performer is chosen. Which dataset should provide the final reported estimate?", "options": ["The same validation set after selecting the winner", "The training set", "An untouched test set", "The union of test and training data used to refit before scoring"]}, {"id": "Q1-46", "topic": "M2", "type": "blank", "stem": "After subtracting a feature's mean and dividing by its standard deviation, the transformed feature has mean ____ and standard deviation ____.", "options": []}, {"id": "Q1-47", "topic": "M3", "type": "tf", "stem": "A test set remains an independent final evaluation set even if its labels were used to choose the best threshold.", "options": []}, {"id": "Q1-48", "topic": "M4", "type": "blank", "stem": "A k-means grouping was learned without response labels. Assigning a new observation to its closest learned center does not change the original fit into ____ learning.", "options": []}, {"id": "Q1-49", "topic": "M7", "type": "tf", "stem": "For ordinary Holt forecasting, the h-step-ahead forecast is current level plus h times current trend.", "options": []}, {"id": "Q1-50", "topic": "M10", "type": "blank", "stem": "For TP=36 and FP=12, precision is ____.", "options": []}], [{"id": "Q2-01", "topic": "M2", "type": "multi", "stem": "Which reasons can justify kernel SVM rather than a strictly linear separator?", "options": ["The feature-label relationship has a curved boundary", "Kernel SVM proves causal mechanisms", "A nonlinear separator may fit patterns missed by a straight hyperplane", "Suitable kernel settings improve validation performance"]}, {"id": "Q2-02", "topic": "M4", "type": "multi", "stem": "A customer-segmentation run reports WSS=26 for k=1 and WSS=0 when every observed customer has a separate center. A manager selects the second run solely because zero looks perfect. Which criticisms are justified?", "options": ["Zero WSS proves that all future customers will be assigned correctly to meaningful groups", "An operationally useful k may be smaller even with positive WSS", "WSS rewards extra clusters and does not by itself establish a useful segmentation", "An elbow and the intended use can help assess whether added clusters are worthwhile"]}, {"id": "Q2-03", "topic": "M7", "type": "multi", "stem": "Daily orders show both an increasing baseline and a repeatable seven-day pattern. A Holt-Winters update is processing Tuesday. Which statements correctly distinguish its components?", "options": ["Trend and seasonality describe the same component and need only one state", "The seasonal comparison uses the previous estimate for the same weekday", "A Tuesday seasonal factor above one indicates a response above the current baseline in the multiplicative formulation", "Changing the response units from dollars to cents changes the number of days in the seasonal cycle"]}, {"id": "Q2-04", "topic": "M10", "type": "multi", "stem": "A random forest and a single classification tree are trained on labeled claims. The forest lets different trees consider different predictor sets and combines their class predictions. Which claims are defensible at the lecture's level?", "options": ["Combining diverse trees can improve predictive performance but still requires validation", "Every forest must be easier to explain as a single sequence of rules than an individual tree", "The forest no longer needs known claim labels because the trees are randomized", "The randomized predictor sets can produce trees with different strengths"]}, {"id": "Q2-05", "topic": "M7", "type": "multi", "stem": "Which statements distinguish additive from multiplicative seasonality?", "options": ["Multiplicative seasonality represents a proportion of level", "A factor of 1 indicates no multiplicative seasonal change", "A factor of zero is always safe in division-based Holt-Winters updates", "Additive seasonality represents a unit offset"]}, {"id": "Q2-06", "topic": "M7", "type": "single", "stem": "A sales team has an ordered response series with a changing mean. After one differencing step, it wants to use two previous modeled values and one previous prediction error. Which ARIMA description matches that specification?", "options": ["ARIMA(2,1,1): two autoregressive lags, one differencing step, one error lag", "ARIMA(1,2,1): one value lag and two error lags", "ARIMA(2,0,1): two lags means differencing occurs automatically", "GARCH(2,1): its variance is the same response as sales"]}, {"id": "Q2-07", "topic": "M3", "type": "single", "stem": "A flexible spline has training MSE zero and much higher held-out MSE than a straight-line model. What is the best interpretation?", "options": ["The line cannot represent any real effect", "The held-out observations should be added to training before comparison", "The spline may fit dataset-specific noise", "The spline must be preferred because its training fit is exact"]}, {"id": "Q2-08", "topic": "M7", "type": "multi", "stem": "A factory uses single exponential smoothing. During a persistent upward shift, a setting with very small alpha changes its forecast only slowly. Which conclusions follow?", "options": ["A larger alpha would put more weight on the latest observation", "Small alpha gives more persistence to the previous level", "Increasing alpha guarantees fewer false alarms and better future predictions", "Changing alpha alone adds an explicit trend and seasonal component"]}, {"id": "Q2-09", "topic": "M10", "type": "single", "stem": "For one repair request, three regression trees predict 8, 10, and 15 hours. The combined forest averages their outputs. Which conclusion is correct?", "options": ["It predicts 15 hours because a forest always selects the largest tree output", "It cannot combine trees that produce different predictions", "It predicts 11 hours; averaging does not prove the actual repair time or a causal explanation", "It predicts the most common class label rather than a numeric time"]}, {"id": "Q2-10", "topic": "M8", "type": "multi", "stem": "A retailer believes marketing emails affect spending differently for younger and older customers. Its current additive regression imposes one common email coefficient. Which lecture-level revisions could represent that variation?", "options": ["Use a tree to define groups with different fitted responses or local relationships", "Increase the common email coefficient and claim that it now differs by age", "Add an email-by-age interaction to the regression", "Choose the revision with the best training fit without evaluating new cases"]}, {"id": "Q2-11", "topic": "M1", "type": "single", "stem": "A restaurant first predicts next week's demand, then chooses purchase quantities under spoilage and shortage costs. What is the role of the demand forecast?", "options": ["An unsupervised class label", "A proof of customer causation", "The final purchasing decision by itself", "A predictive input to a prescriptive decision"]}, {"id": "Q2-12", "topic": "M7", "type": "single", "stem": "A Holt forecast has level 100 and trend -3 response units per observation. The team wants a four-observation-ahead point forecast. Which interpretation is correct?", "options": ["The negative trend proves that a recently introduced policy caused the decline", "The forecast is 88, extending the estimated trend, not guaranteeing four future observations will fall by exactly three", "The forecast is 97 because the horizon never matters", "The forecast is 112 because trend magnitude is always added"]}, {"id": "Q2-13", "topic": "M4", "type": "single", "stem": "A new point is equally far from two learned centers. What is needed for deterministic cluster assignment?", "options": ["A different number of CV folds", "A tie policy", "A logistic response", "A new supervised label for every training point"]}, {"id": "Q2-14", "topic": "M7", "type": "multi", "stem": "Demand forecasts from a mean model are reasonably centered, but forecast errors have periods of small variability and periods of large variability. Management wants to size a reserve against uncertainty. Which statements are appropriate?", "options": ["A larger variance estimate implies greater modeled variability, not necessarily a higher demand mean", "The mean forecast can remain useful even when a separate variance model is needed", "A GARCH model can address changing variance", "A variance model alone determines whether the next error will be positive or negative"]}, {"id": "Q2-15", "topic": "M2", "type": "single", "stem": "A seven-neighbor classifier finds labels A,A,A,B,B,C,C. An analyst rejects the result because no class has a majority. Which response best matches unweighted multiclass k-NN?", "options": ["Class A wins by plurality; the highest vote count need not exceed half of k", "The classifier must return the numerical mean of the letters", "There is necessarily a three-way tie because no class exceeds 50%", "The method can classify only two classes"]}, {"id": "Q2-16", "topic": "M4", "type": "multi", "stem": "Which statements about k-means cluster centers are correct?", "options": ["They are known response labels supplied before fitting", "They need not be observed data points", "An extreme point can pull a center", "They are coordinatewise means under the standard objective"]}, {"id": "Q2-17", "topic": "M4", "type": "single", "stem": "A rescue robot must finish moving on both axes before it can act. The required horizontal and vertical travel times are 5 and 12 seconds, and the motions occur simultaneously. A teammate uses Euclidean distance because it gives 13. What is the best correction?", "options": ["Any norm is equally appropriate because the destination is unchanged", "Euclidean length is always the completion time for two-axis movement", "The completion time is 12 seconds under simultaneous independent motions; the maximum, not the Euclidean length, matches this task", "The completion time is 17 seconds because concurrent movements must be added"]}, {"id": "Q2-18", "topic": "M2", "type": "multi", "stem": "A loan team has amount, payment method, repayment outcome, and a late-fee total recorded after the repayment deadline. It wants to predict repayment before approving a new loan. Which statements are correct?", "options": ["Post-deadline late fees should not be treated as information available at approval", "Changing the algorithm from logistic regression to SVM fixes unavailable-predictor leakage", "Repayment outcome supplies historical labels for supervised learning", "Random splitting makes post-deadline information legitimate for an approval-time prediction"]}, {"id": "Q2-19", "topic": "M4", "type": "multi", "stem": "When comparing repeated k-means starts at the same k, which practices make sense?", "options": ["Ensure the distance and scaling are consistent across runs", "Recognize that different starts can converge to the same solution", "Choose the center ordering with the prettiest labels", "Keep the solution with lower WSS on the same prepared data"]}, {"id": "Q2-20", "topic": "M8", "type": "multi", "stem": "A regression is fitted by minimizing squared prediction errors. Its modeling argument assumes independent, identically distributed normal errors. Which statements connect this to the lecture's likelihood discussion?", "options": ["The best likelihood automatically eliminates overfitting from added predictors", "The error assumptions are part of why that equivalence holds", "Under those assumptions, coefficient estimates minimizing squared errors also maximize the corresponding likelihood", "The result proves that every regression dataset has normal errors"]}, {"id": "Q2-21", "topic": "M3", "type": "multi", "stem": "Which statements distinguish underfitting from overfitting?", "options": ["Both are assessed solely by choosing the largest training R-squared", "Validation can help choose an appropriate flexibility level", "An overly flexible form may fit random structure", "An overly restrictive form may miss real structure"]}, {"id": "Q2-22", "topic": "M6", "type": "single", "stem": "A CUSUM analysis of temperatures signals that a warm period lasted longer in one region. A report attributes the signal to one newly implemented policy. Which evaluation is most defensible?", "options": ["CUSUM labels the cause of each mean shift as part of its output", "The result should be accepted only if its conclusion matches the analyst's prior belief", "Changing the definition until the preferred conclusion appears strengthens the evidence", "The signal depends on the baseline, settings, and data definition; it does not by itself identify the policy as the cause"]}, {"id": "Q2-23", "topic": "M2", "type": "multi", "stem": "A feature's training minimum and maximum are 20 and 60. A new case has value 70. The team applies the same min-max transformation used in training. Which conclusions follow?", "options": ["The scaler must be recomputed using the test cases to force them into the training interval", "An out-of-range transformed value alone proves the raw observation is an error", "A value above one can occur because the new case lies outside the fitted training range", "The new transformed value is 1.25"]}, {"id": "Q2-24", "topic": "M2", "type": "single", "stem": "Two soft-margin SVM settings are tested on the same held-out defect cases. Setting A has more training errors but fewer held-out missed defects and lower stated total decision cost than B. Which recommendation best follows?", "options": ["Favor A for the stated objective, subject to an independent final evaluation after selection", "Favor B because a wider margin always costs more in deployment", "Reject A because any training error makes SVM unusable", "Favor B because fewer training errors overrides the deployment objective"]}, {"id": "Q2-25", "topic": "M2", "type": "single", "stem": "Two analysts use the symbol lambda for different SVM tradeoffs. In one stated objective lambda multiplies the margin-related coefficient penalty; in the other it multiplies the fitting-loss penalty. Which conclusion is defensible?", "options": ["One cannot infer the same tuning direction from the symbol alone; inspect the term it multiplies", "Larger lambda always means fewer training errors regardless of the objective", "The symbol determines whether the model uses labeled or unlabeled data", "The two lambda values must be numerically equal for the models to be comparable"]}, {"id": "Q2-26", "topic": "M2", "type": "single", "stem": "A hard-margin SVM illustration shows two parallel margin boundaries with the closest class points touching them. Another separator also classifies all training points correctly but has a narrower margin. What feature makes the maximum-margin solution preferred under this model's objective?", "options": ["It guarantees that every future observation will be classified correctly", "It predicts a separate probability for every support vector", "Its wider separation from the nearest class points, rather than merely the count of correctly classified training cases", "It must use more predictors than the other separator"]}, {"id": "Q2-27", "topic": "M6", "type": "multi", "stem": "What information is needed to tune change-detection settings sensibly?", "options": ["The assumption that false alarms are always harmless", "Costs of false alarms", "Representative behavior before and after changes", "Costs of detection delay"]}, {"id": "Q2-28", "topic": "M9", "type": "multi", "stem": "Which steps correctly detrend a response for factor-based modeling?", "options": ["Add back the relevant trend when recovering original-scale predictions", "Estimate an appropriate time trend on the permitted training data", "Subtract that fitted trend from observed responses", "Assume detrending always eliminates every seasonal pattern"]}, {"id": "Q2-29", "topic": "M8", "type": "multi", "stem": "Which statements about increasing regression complexity are correct for nested least-squares fits with an intercept on the same training data?", "options": ["Adjusted R-squared may decrease", "Test error is guaranteed to decrease", "Training R-squared cannot decrease", "Training SSE cannot increase"]}, {"id": "Q2-30", "topic": "M2", "type": "multi", "stem": "A feature is standardized to z=(x-50)/10. Which statements are correct?", "options": ["A skewed distribution necessarily becomes normal", "x=70 maps to z=2", "Every resulting z must be between zero and one", "x=30 maps to z=-2"]}, {"id": "Q2-31", "topic": "M10", "type": "multi", "stem": "A repair tree first asks whether machine age is below 30 months. For the older branch it then asks whether load is below 50 units. A new machine is 40 months old with load 60. The reached leaf has only two training cases. Which statements are justified?", "options": ["Use the response estimate associated with the reached leaf", "Follow the older-machine branch and then the load-at-least-50 branch", "The very small leaf warrants concern about the stability of its prediction", "Average predictions from all leaves because every tree is a forest"]}, {"id": "Q2-32", "topic": "M9", "type": "single", "stem": "Two centered and standardized predictors measure production position and elapsed production day. They are highly positively correlated. PCA produces a dominant first component. Which interpretation is defensible?", "options": ["The component with the larger eigenvalue must explain the same percentage of response variation", "Highly correlated predictors force the two component variances to be equal", "PCA has established which variable causes failures", "Most predictor variation lies along a shared direction; this does not prove that component is the best predictor of failure time"]}, {"id": "Q2-33", "topic": "M10", "type": "multi", "stem": "A logistic model predicts 0.70 probability of repayment for one applicant, and the lending rule grants a loan at 0.80 or above. Which statements distinguish the outputs?", "options": ["The model must output 0.70 dollars as the predicted loan amount", "A different decision threshold can change the action without changing the fitted probability for this applicant", "Under the stated rule the applicant is classified below the loan-granting threshold", "The probability estimate is 0.70"]}, {"id": "Q2-34", "topic": "M7", "type": "single", "stem": "A time series has a drifting mean, while differences between consecutive observations fluctuate around a much more stable mean. Which ARIMA choice addresses the described feature most directly?", "options": ["Increasing the number of error lags guarantees that the mean becomes stationary", "A differencing step, with its adequacy checked on the resulting series", "PCA always removes temporal drift even when fitted without time information", "Replacing the response values with a variance forecast necessarily removes the drift"]}, {"id": "Q2-35", "topic": "M3", "type": "single", "stem": "A forecasting model will use data through Friday to predict Saturday. Which evaluation design best mirrors deployment?", "options": ["Use the same observations for fitting and testing", "Train on earlier periods and validate on later periods", "Predict Friday using Saturday's realized response", "Randomly intermingle future and past records for every fit"]}, {"id": "Q2-36", "topic": "M5", "type": "multi", "stem": "Which statements about large residuals are correct?", "options": ["They can indicate a missing predictor or wrong model form", "They prove the corresponding observation is invalid", "They merit investigation in the intended application", "They can indicate data errors"]}, {"id": "Q2-37", "topic": "M3", "type": "multi", "stem": "Which preprocessing practices avoid leakage in cross-validation?", "options": ["Fit PCA to all observations before making folds", "Estimate feature means on each fold's training portion", "Apply those fitted means to the held-out fold", "Select predictors using only the fold's training outcomes"]}, {"id": "Q2-38", "topic": "M9", "type": "multi", "stem": "Which conclusions follow from retaining all orthonormal PCA components of a feature space?", "options": ["The number of predictors automatically becomes one", "The representation changes coordinates", "No information is discarded solely by the full rotation", "Every component becomes causally interpretable"]}, {"id": "Q2-39", "topic": "M8", "type": "multi", "stem": "Two regressions predict a numeric response on the same held-out observations. A has lower held-out squared error but uses a sensor that becomes available only after the decision; B has slightly higher error using timely attributes. Which conclusions follow?", "options": ["A must be chosen because squared error is the only relevant modeling consideration", "Prediction-time feasibility can favor B despite its higher measured error", "A's reported error does not establish that it can serve the stated decision time", "Replacing A with a tree automatically makes the late sensor timely"]}, {"id": "Q2-40", "topic": "M7", "type": "multi", "stem": "Which statements about ARIMA's moving-average component are correct?", "options": ["Its order q counts innovation lags", "It can coexist with an autoregressive component", "It uses past innovations", "It necessarily averages the last q raw observations equally"]}, {"id": "Q2-41", "topic": "M3", "type": "single", "stem": "Two model families are compared using five equally sized validation folds. A averages error 6 but varies markedly between folds; B averages 6.2 with more stable results. Which claim is most appropriate?", "options": ["A's average proves it will outperform B in every deployment population", "B should be preferred solely because its error is higher", "The winning fold from A is necessarily the final fitted model", "A has the lower reported average, but the small difference and variation warrant caution and a separate final evaluation"]}, {"id": "Q2-42", "topic": "M6", "type": "single", "stem": "For upper CUSUM, previous S=3, x=7, mu=10, C=1. What is the new statistic?", "options": ["21", "4", "0", "-1"]}, {"id": "Q2-43", "topic": "M1", "type": "multi", "stem": "Which statements about inference and prediction are reasonable?", "options": ["Predictive success alone establishes the mechanism of a relationship", "Maximum flexibility always minimizes future error", "A less interpretable method may be useful when predictive accuracy is the priority", "An interpretable model can help explain modeled associations"]}, {"id": "Q2-44", "topic": "M5", "type": "single", "stem": "A heartbeat sequence lacks one expected beat, but none of the observed amplitudes is unusual. Which representation can expose a point outlier?", "options": ["Time between consecutive beats", "Only the sensor's ZIP code", "Unordered amplitudes alone", "A constant indicator for every observation"]}, {"id": "Q2-45", "topic": "M8", "type": "multi", "stem": "A regression has R-squared=.60 on its training data. Adding predictors raises it to .70, but held-out prediction error increases. Which statements are justified?", "options": ["The higher R-squared proves better held-out predictions", "The additional predictors may be fitting patterns that do not generalize", "The training fit improved by this measure", "Held-out error and complexity considerations matter when selecting the specification"]}, {"id": "Q2-46", "topic": "M4", "type": "blank", "stem": "For coordinate differences of 6 and 8, Manhattan distance is ____.", "options": []}, {"id": "Q2-47", "topic": "M5", "type": "tf", "stem": "If removing an outlier improves fit, that alone proves removal is appropriate for the intended application.", "options": []}, {"id": "Q2-48", "topic": "M7", "type": "blank", "stem": "With level=200, trend=5, and the next multiplicative seasonal factor=1.2, the one-step forecast is ____.", "options": []}, {"id": "Q2-49", "topic": "M8", "type": "tf", "stem": "A low p-value is sufficient evidence that changing the predictor will cause the estimated change in the response.", "options": []}, {"id": "Q2-50", "topic": "M10", "type": "blank", "stem": "If a classification leaf has 9 positive and 3 negative training cases, its empirical positive fraction is ____.", "options": []}], [{"id": "Q3-01", "topic": "M3", "type": "multi", "stem": "Which split designs can address nonrepresentative subsets?", "options": ["Stratify by important classes when appropriate", "Check whether systematic rotation aligns with periodic structure", "Consider relevant regimes or groups", "Assume random splits always preserve every rare condition"]}, {"id": "Q3-02", "topic": "M8", "type": "multi", "stem": "A regression coefficient is estimated at -4, with a reported 95% confidence interval from -9 to 1. The manager says this proves there is no association and proposes deleting the predictor without checking prediction quality. Which statements are warranted?", "options": ["The interval proves the coefficient is exactly zero", "The estimate is negative, but the reported uncertainty includes positive and negative values", "Predictive usefulness should be evaluated rather than inferred solely from whether the interval includes zero", "The interval includes zero, so it does not give strong evidence against a zero coefficient at the matching conventional level"]}, {"id": "Q3-03", "topic": "M7", "type": "single", "stem": "A sensor team has an ordered numeric series and two requests: forecast the next reading and alarm on a sustained increase from an established baseline. Which pair most directly assigns the lecture methods to those tasks?", "options": ["ARIMA or smoothing for the reading forecast, and CUSUM for accumulated evidence of an upward change", "CUSUM for the exact future reading, and PCA for the change alarm", "GARCH alone for both the expected reading and its exact change date", "K-means for the next reading and logistic regression without labels for the shift"]}, {"id": "Q3-04", "topic": "M9", "type": "single", "stem": "Two orthogonal PCA loadings produce a high-variance component unrelated to outcome and a low-variance component that separates classes. What does PCA alone recommend retaining first?", "options": ["Both components must receive equal ranks", "The outcome-separating component by definition", "No component because classes exist", "The high-variance component"]}, {"id": "Q3-05", "topic": "M2", "type": "multi", "stem": "A scaled linear SVM assigns zero coefficient to x2, while a tree using the same labeled data splits on x2 in one region. Which conclusions are justified?", "options": ["x2 can matter in a different representation or regional rule", "x2 does not affect this particular fitted linear SVM score", "The tree's use of x2 proves its predictions are better", "The zero coefficient proves x2 has no real-world association or causal effect under any circumstances"]}, {"id": "Q3-06", "topic": "M7", "type": "multi", "stem": "Two level-only smoothing models forecast weekly sales. One uses alpha=.8, the other .2. Last week had a one-off promotion unlikely to recur. Which statements correctly describe the tradeoff?", "options": ["The promotion's relevance to the forecast target should be investigated rather than judging settings solely by that week's fit", "The .8 update puts more weight on the promotion observation", "The .2 update retains more of the previous level", "The larger alpha is guaranteed to forecast ordinary future weeks better"]}, {"id": "Q3-07", "topic": "M4", "type": "multi", "stem": "Which changes alter the substantive clustering problem?", "options": ["Change the distance metric", "Switch from miles to dollars on one dimension without scaling policy", "Rename clusters from 1,2 to blue,red while keeping membership unchanged", "Analyze day and night separately when their distributions differ"]}, {"id": "Q3-08", "topic": "M7", "type": "single", "stem": "A multiplicative Holt-Winters implementation begins with seasonal factors of one and initial trend zero. The analyst reports that the underlying process has no seasonality or trend because those are the starting values. What is the best correction?", "options": ["An initial zero trend prevents later trend updates", "A factor of one proves every seasonal phase is identical for all future periods", "Seasonal factors of one mean all response observations equal one", "Initialization is a starting estimate; later observations update the states and can reveal trend or seasonal differences"]}, {"id": "Q3-09", "topic": "M6", "type": "single", "stem": "A clinic monitors reductions in service time with lower CUSUM S_new=max(0,S_previous+mu-x-C). Baseline is 20, allowance 1, previous statistic 2, and new time 16. The alarm threshold is 6, triggered only when S_new>6. Which conclusion is correct?", "options": ["The statistic is 5 and the alarm proves a staffing change caused the improvement", "The statistic is 7 because the allowance should be added", "The statistic is zero because only upward changes can be detected", "The statistic is 5; the low observation adds downward-change evidence but does not yet trigger this rule"]}, {"id": "Q3-10", "topic": "M2", "type": "single", "stem": "A k-NN model has good training behavior but poor validation performance after adding many irrelevant dimensions. What is a sensible next step?", "options": ["Choose k by the final test error repeatedly", "Convert all labels to missing values", "Keep every dimension because more features always help", "Evaluate feature selection or meaningful weighting inside validation"]}, {"id": "Q3-11", "topic": "M10", "type": "multi", "stem": "A classification tree splits a leaf into two small leaves and obtains perfect training labels in both. Held-out classification becomes worse. Which statements correctly interpret the result?", "options": ["The split improved training fit", "Pruning or increasing the support required for a split can be sensible responses", "The new leaves may be too specialized to their training cases", "Perfect training labels prove the split captured a stable population rule"]}, {"id": "Q3-12", "topic": "M10", "type": "single", "stem": "A retailer compares an interpretable single tree with a random forest. The forest performs better on validation, but the retailer must explain each declined application through a short sequence of rules. Which conclusion follows?", "options": ["The forest automatically supplies one unique branch path explaining the whole ensemble", "The tree must be best because interpretable models always predict better", "Predictive performance and explanation requirements both matter; the forest's validation gain does not by itself resolve the choice", "The objective can ignore explanation constraints whenever many trees are available"]}, {"id": "Q3-13", "topic": "M3", "type": "multi", "stem": "A team compares several SVM penalties and several k-NN neighborhood sizes using cross-validation. One SVM specification has the best mean validation result. Which actions are appropriate?", "options": ["Refit that selected specification using all non-test observations", "Use an untouched final test set to assess the selected procedure", "Treat the mean validation result as an independent final test after using it to choose the winner", "Retain only the coefficients from the best-scoring fold because they must be the final optimum"]}, {"id": "Q3-14", "topic": "M8", "type": "single", "stem": "On the same dataset, model A has slightly worse likelihood but fewer parameters than B. A has lower AIC; B has lower unpenalized fitting error. Which conclusion is supported?", "options": ["Different criteria cannot disagree when the data are the same", "AIC must always select the model with the lowest training error", "The criteria emphasize different tradeoffs, so B's better fit does not refute AIC's preference for A", "A's lower AIC proves every coefficient is causal"]}, {"id": "Q3-15", "topic": "M4", "type": "multi", "stem": "A k-means plan has WSS values 400, 210, 110, 98, and 90 for k=1 through 5. Managers can staff at most three service centers. Which interpretations make sense?", "options": ["The curve suggests a candidate elbow near three clusters", "The smallest listed WSS means five centers must be selected despite the staffing constraint", "The elbow is evidence to assess alongside service coverage, not proof that three is universally optimal", "The operational limit supports considering three or fewer centers"]}, {"id": "Q3-16", "topic": "M9", "type": "multi", "stem": "PCA produces two components from centered, standardized production measurements. A loading combines several measurements, rather than identifying one original column to keep. Which distinctions are correct?", "options": ["A large component loading establishes an original feature's causal importance", "Keeping only the first component is identical to selecting whichever original feature has the largest mean", "PCA is feature extraction because it creates combinations of the original features", "The loadings describe directions used to compute component scores"]}, {"id": "Q3-17", "topic": "M2", "type": "multi", "stem": "A rare toxic class is costly to miss. Which classification adjustments can be appropriate?", "options": ["Evaluate the resulting false alarms and total cost", "Use a lower toxic-probability threshold if miss costs dominate", "Force a threshold of .5 because probabilities require symmetry", "Increase the penalty for missing toxic cases"]}, {"id": "Q3-18", "topic": "M8", "type": "multi", "stem": "A regression estimates a $0.001 spending difference per exposure unit with a very small p-value. The action needed to change exposure costs much more than the expected spending difference. Which statements are justified?", "options": ["The coefficient's units and practical size matter", "The cost comparison belongs to the decision question in addition to the modeling question", "A small p-value guarantees the intervention is worthwhile and causal", "Statistical evidence for an association does not ensure economically valuable action"]}, {"id": "Q3-19", "topic": "M5", "type": "multi", "stem": "A clustering analysis identifies a small but verified customer group far from most observations. Removing the group improves WSS and a regression's fit. The business wants to serve all customer types. Which statements are defensible?", "options": ["Better fit alone is not a sufficient reason to delete legitimate target customers", "The group may reflect a meaningful segment rather than bad data", "Separate analysis or reporting may help preserve the group's operational importance", "All small clusters are measurement errors by definition"]}, {"id": "Q3-20", "topic": "M10", "type": "multi", "stem": "A regression-tree split reduces within-node response variation, but one proposed child has very few observations. Which steps reflect the lecture's branching and pruning ideas?", "options": ["Keep every split with any training improvement regardless of leaf support", "Use a quality-related splitting criterion together with safeguards against overfitting", "Check whether the split improves estimation on separate data during pruning", "Require enough data in each resulting leaf rather than splitting solely for a training improvement"]}, {"id": "Q3-21", "topic": "M10", "type": "single", "stem": "An airport needs expected arrival counts from time of day and holiday status. A second project has few labeled cases but useful expert beliefs about regression coefficients. Which pairing matches the survey introductions?", "options": ["Poisson regression requires the same arrival rate at every time and holiday status", "PCA for arrival probabilities and CUSUM for prior coefficient beliefs", "Poisson regression for the count-rate task; Bayesian regression to combine the second project's prior information with data", "Bayesian regression guarantees that experts override all observed evidence"]}, {"id": "Q3-22", "topic": "M2", "type": "multi", "stem": "A classifier uses a horizontal boundary x2=5. Points above it are positive. A tree built from the same data uses both x1 and x2 and makes fewer training errors. Which statements are supported?", "options": ["A horizontal boundary means that x1 must control the class", "The tree may use a predictor that this particular linear rule does not use", "Fewer training errors establish the tree's deployment superiority", "x1 does not change the class under the stated horizontal rule"]}, {"id": "Q3-23", "topic": "M2", "type": "single", "stem": "A sensor feature is constant in all training observations. The team wants to standardize every feature and use k-NN. Which handling is defensible?", "options": ["The constant feature guarantees better neighbor discrimination", "An undefined standardized coordinate should be silently treated as an extremely large distance", "The standardized feature must become a normal distribution", "Recognize the zero standard deviation and handle the feature explicitly rather than dividing by zero"]}, {"id": "Q3-24", "topic": "M1", "type": "multi", "stem": "A delivery company groups unlabeled route profiles, predicts delay probability from labeled deliveries, and chooses extra driver staffing under a budget. Which statements correctly describe the pipeline?", "options": ["Grouping profiles can be an unsupervised descriptive step", "Estimating delay probability is a supervised predictive step", "The budget-constrained staffing choice is a prescriptive step", "Every step is the same task because each uses delivery data"]}, {"id": "Q3-25", "topic": "M7", "type": "multi", "stem": "Which quantities enter the lecture's multiplicative Holt-Winters level update?", "options": ["A level smoothing coefficient alpha", "Previous level plus previous trend", "Current observation divided by the previous same-phase seasonal factor", "Tomorrow's actual observed response"]}, {"id": "Q3-26", "topic": "M2", "type": "single", "stem": "A linear classifier predicts positive when 2*x1-3*x2+6>0. An observation starts at (0,1); only x2 increases to 3. Which interpretation is correct?", "options": ["Increasing either predictor must always move toward the same class", "The prediction stays positive because x1 did not change", "The prediction changes from positive to negative; the score is a decision quantity rather than automatically a probability", "The score at the starting point is a valid probability of three"]}, {"id": "Q3-27", "topic": "M10", "type": "multi", "stem": "A clinician estimates infection probability at .08. An unnecessary follow-up costs $10; missing an infection costs $200; correct decisions are free. Compare follow-up to no follow-up under these stated costs. Which statements are correct?", "options": ["Expected no-follow-up error cost is .08*$200=$16", "Expected follow-up error cost is .92*$10=$9.20", "Follow-up has lower stated expected error cost, although this simplified calculation does not include unstated consequences", "No follow-up must be preferred whenever probability is below .50"]}, {"id": "Q3-28", "topic": "M7", "type": "multi", "stem": "A process records one response per completed part. Each 80-part batch lasts a variable number of days, and early parts repeatedly have lower operating hours before failure. Which modeling interpretations are justified?", "options": ["An item-indexed seasonal analysis can use a period of 80", "A positive trend in this response would indicate increasing operating hours before failure across the index", "The seasonal pattern itself proves workers are careless at the start of each batch", "A multiplicative early-batch factor below one corresponds to lower hours before failure"]}, {"id": "Q3-29", "topic": "M4", "type": "multi", "stem": "A new customer is assigned to the closest of several stored k-means centers. It is much farther from every center than any training customer was. Which statements are valid?", "options": ["Assigning a new customer changes the original unlabeled clustering into a supervised classification fit", "The assignment proves that it is a typical member of that group", "The nearest-center rule can still assign it to a cluster", "Its unusual distance warrants checking whether the learned representation covers this case"]}, {"id": "Q3-30", "topic": "M10", "type": "multi", "stem": "Two infection models have different ROC curves. Model A has a larger AUC; at the clinic's chosen operating thresholds, model B has lower expected decision cost. Which conclusions are justified?", "options": ["Threshold choice and error consequences need consideration beyond AUC", "Larger AUC guarantees the lower cost at every threshold and prevalence", "The clinic can favor B under its stated operating costs", "AUC summarizes ranking across positive and negative cases"]}, {"id": "Q3-31", "topic": "M3", "type": "single", "stem": "The same patient's measurements appear in both training and validation, although deployment targets new patients. What is the concern?", "options": ["The response becomes unsupervised", "All measurements must be discarded", "Validation can benefit from patient-specific overlap", "This guarantees pessimistic validation"]}, {"id": "Q3-32", "topic": "M7", "type": "multi", "stem": "A time series has roughly stable mean and variability, while another has a strong upward trend. Which statements match the lecture's stationarity discussion?", "options": ["One difference guarantees suitability for every possible time series", "Whether differencing helps should be assessed rather than assumed", "Differences may make some trending series more stable", "The stable series better resembles the lecture's stationary-data description"]}, {"id": "Q3-33", "topic": "M7", "type": "multi", "stem": "A level-only smoothing model and Holt give the same current level. The series has an estimated positive trend. Which statements about their ordinary forecasts are correct?", "options": ["Single smoothing acquires an explicit trend state merely by raising alpha", "A positive trend forecast identifies the operational cause of the rising response", "Holt can extend the estimated trend over the forecast horizon", "Level-only smoothing gives a flat point forecast at its current level"]}, {"id": "Q3-34", "topic": "M10", "type": "multi", "stem": "Which are valid reasons for pruning or limiting a tree?", "options": ["Children would have too few observations", "A split's training improvement does not persist on validation", "Complexity encourages fitting noise", "Every deeper tree is guaranteed to improve future prediction"]}, {"id": "Q3-35", "topic": "M5", "type": "multi", "stem": "Which circumstances can generate a genuine outlying record?", "options": ["A transcription error known to have changed the recorded value", "A one-time publicity event affecting sales", "A rare weather-related delivery disruption", "Natural tail variation in a large sample"]}, {"id": "Q3-36", "topic": "M6", "type": "single", "stem": "Upper CUSUM is reset when its raw cumulative value becomes negative. What purpose does this serve?", "options": ["It estimates a seasonal factor", "It avoids carrying downward evidence that delays a later upward alarm", "It makes false alarms impossible", "It proves the process mean has changed"]}, {"id": "Q3-37", "topic": "M7", "type": "single", "stem": "A forecaster supplies expected returns. A risk manager instead asks how large their fluctuations may be during a volatile period. Which method most directly serves that second target?", "options": ["CUSUM, because a change alarm is itself the variance forecast", "Logistic regression, because a binary-event probability is the same quantity as return variance", "GARCH, because its primary output is time-varying variance", "K-means, because groups of historical returns automatically give tomorrow's variance"]}, {"id": "Q3-38", "topic": "M6", "type": "multi", "stem": "Which quantities should remain distinct in a CUSUM analysis?", "options": ["Baseline expectation mu", "Per-observation allowance C", "Number of features as a mandatory synonym for T", "Cumulative alarm threshold T"]}, {"id": "Q3-39", "topic": "M8", "type": "multi", "stem": "When comparing AIC or BIC scores, which precautions matter?", "options": ["Assume raw scores from arbitrarily transformed response scales are automatically comparable", "Use comparable observations and likelihood definitions", "Prefer smaller values for the stated criteria", "Count parameters consistently"]}, {"id": "Q3-40", "topic": "M9", "type": "single", "stem": "A positive response is transformed with Box-Cox before regression. The fitted model now predicts transformed values. Which reporting practice is defensible at the survey level?", "options": ["Read a coefficient on the transformed scale as an identical raw-unit change without checking", "Identify the transformed response and explain how predictions relate to the original units before making operational claims", "Use the original response units for the transformed predictions without any conversion", "Claim the transformation proves all omitted variables are irrelevant"]}, {"id": "Q3-41", "topic": "M4", "type": "multi", "stem": "Which statements distinguish clustering from classification?", "options": ["A cluster label must have a known causal meaning", "A new point can be assigned to a discovered cluster without known response", "Clustering discovers groups from feature similarity", "Classification learns from known response categories"]}, {"id": "Q3-42", "topic": "M1", "type": "multi", "stem": "Which concerns should guide the choice between an interpretable regression and a forest?", "options": ["Need to explain individual modeled relationships", "Whether decision-makers can use the output", "Held-out predictive performance", "Which method has the most impressive name"]}, {"id": "Q3-43", "topic": "M8", "type": "single", "stem": "A binary predictor is one for premium members and zero otherwise. In an additive model its coefficient is 7. What is its interpretation?", "options": ["Premium membership is associated with a seven-unit predicted response difference holding other predictors fixed", "There must be seven membership categories", "The intercept must be seven", "Premium members have seven times the probability"]}, {"id": "Q3-44", "topic": "M3", "type": "multi", "stem": "Which statements about training and validation randomness are correct?", "options": ["Validation removes all randomness from measured quality", "A fitted model can capture accidental training patterns", "A validation winner can benefit from accidental validation patterns", "A separate test set reduces selection-related optimism"]}, {"id": "Q3-45", "topic": "M9", "type": "single", "stem": "A response is detrended as r=y-(10+2*t). At t=5 a model predicts r=3. What original-scale response is predicted?", "options": ["3", "13", "23", "-17"]}, {"id": "Q3-46", "topic": "M2", "type": "tf", "stem": "A linear SVM score of 2.3 is automatically a predicted probability of 2.3.", "options": []}, {"id": "Q3-47", "topic": "M3", "type": "blank", "stem": "In six-fold CV, each non-test observation serves as a validation observation ____ time(s).", "options": []}, {"id": "Q3-48", "topic": "M6", "type": "tf", "stem": "A larger CUSUM threshold usually requires more accumulated evidence before an alarm.", "options": []}, {"id": "Q3-49", "topic": "M8", "type": "blank", "stem": "The regression residual for observed y=12 and fitted y=9 is ____.", "options": []}, {"id": "Q3-50", "topic": "M10", "type": "blank", "stem": "With actual positive prevalence .1, sensitivity .8, and specificity .9, expected TP per 1,000 observations is ____.", "options": []}], [{"id": "Q4-01", "topic": "M8", "type": "multi", "stem": "An analyst says the maximum-likelihood fit chooses parameters that make the observed data most compatible with the assumed statistical model. Another says it chooses parameters that make every future outcome certain. Which statements are valid?", "options": ["The first description reflects the purpose of maximum-likelihood fitting", "A high likelihood makes all future observations deterministic", "Improved likelihood alone can justify unlimited increases in model complexity", "The likelihood calculation depends on the specified model and assumptions"]}, {"id": "Q4-02", "topic": "M9", "type": "single", "stem": "A regression is fit using two principal components instead of two original, correlated predictors. A manager wants to interpret one fitted component slope as the effect of changing only the first original predictor. What is the best response?", "options": ["A regression on components cannot produce predictions", "PCA components prove independent causal effects of original variables", "Every component is just the original feature with the largest mean", "A component combines original predictors, so its coefficient cannot automatically be read as the effect of one original feature alone"]}, {"id": "Q4-03", "topic": "M9", "type": "single", "stem": "A PCA transformation has been learned from training predictors. A new production case needs a regression prediction in that component space. Which procedure is appropriate?", "options": ["Use the new case's response to choose which component to retain before predicting it", "Fit a new PCA to the single new case so its axes are tailored to that prediction", "Substitute an original raw feature for a component because they necessarily share the same scale", "Apply the stored centering/scaling and loadings, then use the fitted component-space regression"]}, {"id": "Q4-04", "topic": "M6", "type": "multi", "stem": "Two CUSUM definitions of a hot season give different results. The analyst selects the definition supporting a preferred conclusion, hides the other analysis, and attributes the shift to a policy. Which concerns are warranted?", "options": ["Selecting only a favorable definition can bias the reported conclusion", "A transparent analysis distinguishes a detected change from its explanation", "Results should disclose relevant definitions and sensitivity to them", "The alarm itself identifies the policy as the causal mechanism"]}, {"id": "Q4-05", "topic": "M2", "type": "single", "stem": "A hard-margin linear SVM is proposed for labeled observations whose classes overlap in the available predictor space. The team insists that every training observation must lie on the correct side with a nonzero margin. What is the most sensible lecture-level response?", "options": ["Switching labels from 0/1 to -1/+1 removes overlap in the predictors", "Any labeled dataset has a perfect linear separation if its sample is large enough", "The strict hard-margin requirement may be infeasible; consider a soft-margin tradeoff and validate the resulting classifier", "A failed hard-margin fit proves the labels are all measurement errors"]}, {"id": "Q4-06", "topic": "M7", "type": "single", "stem": "A level-only smoothing model has current estimate 73. A colleague forecasts 73 tomorrow and 83 five observations ahead because the horizon is longer. No trend component has been fitted. Which statement is correct?", "options": ["The ordinary point forecasts remain 73 at both horizons; a systematic trend extension requires a trend-capable specification", "A flat point forecast means future observations have no variability", "A longer horizon must always produce a larger expected response", "Every smoothing model automatically adds two units per future observation"]}, {"id": "Q4-07", "topic": "M10", "type": "multi", "stem": "Default is labeled positive. For the same fixed logistic scores, the bank raises the classification threshold from .2 to .7. Which consequences are generally expected?", "options": ["The set of positive predictions can only shrink or stay the same", "False positives can fall, while false negatives can rise", "The fitted probabilities themselves must rise to compensate", "The change is automatically better without considering error costs"]}, {"id": "Q4-08", "topic": "M8", "type": "multi", "stem": "Two regression predictors move almost together across the data. The fitted model predicts reasonably well, but their individual coefficients change substantially when the sample changes slightly. Which conclusion is defensible?", "options": ["PCA can be considered as a representation change, but it will not establish causal importance", "The larger coefficient must always be the more causally important predictor", "The predictors provide overlapping information, so separate coefficient interpretations can be unstable even when predictions remain useful", "Prediction quality proves the two predictors have independently identified causal effects"]}, {"id": "Q4-09", "topic": "M7", "type": "single", "stem": "A Holt model's current trend is positive, while recent observations alternate in a repeatable weekly pattern around that trend. Which model-structure conclusion is reasonable?", "options": ["Increasing beta alone creates seven separate weekday effects", "Any positive trend implies every later observation exceeds the previous one", "The weekly pattern proves that trend estimation is impossible", "A trend component does not by itself model repeating seasonal phases; a seasonal specification may be needed"]}, {"id": "Q4-10", "topic": "M3", "type": "single", "stem": "Two equally good candidate methods obtain validation accuracies .81 and .85 due partly to sampling noise. Why may the chosen .85 overstate quality?", "options": ["Training data cannot contain random patterns", "Accuracy must always be exactly .5", "Selecting the winner favors favorable validation fluctuations", "The validation set has no labels"]}, {"id": "Q4-11", "topic": "M7", "type": "multi", "stem": "A reliability analysis uses multiplicative seasonality. Early-batch items have factor .8, later items 1.2, and the response is hours of operation before first breakdown. Which statements are supported?", "options": ["The early factor proves that workers are still learning the job at batch start", "Early-batch response levels are lower relative to the current baseline", "The seasonal pattern does not by itself determine the cause", "Higher hours before breakdown correspond to longer observed reliability"]}, {"id": "Q4-12", "topic": "M3", "type": "multi", "stem": "Which uses of test data preserve its final evaluation role?", "options": ["Compute a previously selected evaluation metric", "Apply a locked preprocessing transformation", "Inspect errors and choose a new kernel using test labels before reporting the old test score", "Apply the already selected model"]}, {"id": "Q4-13", "topic": "M6", "type": "multi", "stem": "An upper CUSUM statistic updates to exactly 10. The written alarm rule is S>T with threshold T=10. A manager treats equality as an alarm and claims a defect cause has been proved. Which statements are correct?", "options": ["The allowance and the alarm threshold are different quantities and should not be confused", "A different rule using S>=T would have different boundary behavior", "Either rule directly establishes the cause of the process change", "Equality does not trigger this particular strict-inequality rule"]}, {"id": "Q4-14", "topic": "M2", "type": "single", "stem": "An organization has labeled numeric outcomes and wants to predict a new case from similar historical cases. Three nearest responses are 4, 10, and 13. Which distinction is correct?", "options": ["The predicted value of 9 guarantees the new case has response 9", "k-means and k-NN regression are interchangeable because each uses k", "Both variants must return whichever response value is most frequent", "k-NN regression predicts their average, 9; k-NN classification would vote on category labels instead"]}, {"id": "Q4-15", "topic": "M8", "type": "multi", "stem": "Which residual plots suggest different modeling issues?", "options": ["A normal-looking raw predictor histogram proves every regression assumption", "Long same-sign runs over time can suggest serial dependence", "Systematic curvature can suggest wrong functional form", "A funnel can suggest nonconstant error variance"]}, {"id": "Q4-16", "topic": "M8", "type": "multi", "stem": "A straight-line regression misses a clear curved response pattern. A polynomial term or regression spline improves held-out prediction. Which statements are defensible?", "options": ["Any curvature requires a classification model rather than regression", "The improvement proves which physical mechanism caused the curvature", "A regression can include nonlinear functions of predictors while remaining linear in its fitted coefficients", "A spline can join different polynomial pieces smoothly"]}, {"id": "Q4-17", "topic": "M4", "type": "multi", "stem": "Which behaviors are expected within a standard k-means run under its squared-distance objective?", "options": ["The objective need not reach the global optimum", "Updating a nonempty cluster to its mean cannot increase its assigned-point SSE", "The objective increases every time the centers are recomputed", "Assigning points to closest centers cannot increase WSS"]}, {"id": "Q4-18", "topic": "M9", "type": "multi", "stem": "A team replaces original features with PCA components before regression and retains only a few components. Which statements are defensible?", "options": ["Loadings describe combinations of the original features", "The retained fraction of predictor variance equals the regression's response variance explained", "The component representation may make original-feature interpretation harder", "Dropping components can discard information useful for predicting the response"]}, {"id": "Q4-19", "topic": "M1", "type": "single", "stem": "A retailer summarizes spending patterns by customer group, predicts next-month spending, and allocates marketing under a fixed budget. Which distinction is correct?", "options": ["A descriptive relationship is automatically a causal effect of advertising", "A spending forecast alone determines the best marketing allocation without costs or constraints", "All three are unsupervised clustering tasks because they concern customers", "Summary, prediction, and constrained allocation address descriptive, predictive, and prescriptive questions respectively"]}, {"id": "Q4-20", "topic": "M4", "type": "multi", "stem": "Which goals can clustering support in the lectures?", "options": ["Learning a known yes/no response without using that response", "Targeted marketing segments", "Initial investigation of different subpopulations", "Geographic facility placement"]}, {"id": "Q4-21", "topic": "M7", "type": "multi", "stem": "Which statements distinguish smoothing from forecasting?", "options": ["A current smoothed level can use the current observed value", "Scoring a smoothed value as if it were an advance forecast can be optimistic", "Future observations may be used whenever smoothing coefficients are below one", "A forecast for the current value must be produced before observing it"]}, {"id": "Q4-22", "topic": "M1", "type": "multi", "stem": "A model for tomorrow's staffing uses tomorrow's realized queue length as a predictor and achieves excellent validation error. The decision is made tonight. Which statements are warranted?", "options": ["A valid evaluation should reproduce the information available when staffing is chosen", "Excellent retrospective error can therefore misrepresent feasible deployment performance", "Changing from regression to random forest necessarily repairs the information timing", "The predictor is unavailable at decision time"]}, {"id": "Q4-23", "topic": "M6", "type": "multi", "stem": "Which conclusions are supported by a CUSUM alarm?", "options": ["Accumulated evidence has crossed the chosen threshold", "A false alarm remains possible", "The evidence is consistent with a shift relative to the baseline", "The cause of the shift is proven"]}, {"id": "Q4-24", "topic": "M2", "type": "multi", "stem": "A fraud classifier deliberately shifts its decision boundary so more borderline cases are investigated. Missed fraud is expensive, while investigations also consume resources. Which statements follow?", "options": ["More true fraud may be caught, but unnecessary investigations can also increase", "The change should be evaluated using the relevant consequences of both error types", "Shifting a boundary is a decision tradeoff rather than proof that the probability of fraud changed", "Catching more fraud proves that the new boundary minimizes total cost"]}, {"id": "Q4-25", "topic": "M10", "type": "multi", "stem": "A classification tree has leaves with 18 of 20, 14 of 20, and 1 of 1 training cases classified correctly. A colleague averages the three percentages and uses the resulting high value to prove deployment quality. Which statements identify the errors?", "options": ["The one-case leaf is a potential overfitting warning", "Training accuracy should weight leaves by their case counts, giving 33/41", "Even correctly computed training accuracy is not independent deployment evidence", "Percentages from differently sized leaves must be weighted by their case counts for overall accuracy"]}, {"id": "Q4-26", "topic": "M5", "type": "multi", "stem": "A medicine-delivery dataset contains real rare delays caused by storms. Which approaches can preserve relevant risk?", "options": ["Assess how excluding delays changes operational optimism", "Model disruption probability separately from ordinary delivery duration", "Retain delays if the target includes such conditions", "Discard all delays merely because they are inconvenient to fit"]}, {"id": "Q4-27", "topic": "M7", "type": "multi", "stem": "Which are legitimate distinctions between ARIMA and GARCH?", "options": ["GARCH primarily models conditional variance", "GARCH uses squared shocks in its variance recursion", "ARIMA primarily models the conditional level/mean", "GARCH must include a differencing order d identical to ARIMA"]}, {"id": "Q4-28", "topic": "M5", "type": "single", "stem": "A boxplot flags a delivery delay, and a regression also gives it a large residual. The delay is verified as real and caused serious medicine spoilage. Which handling best matches the target of predicting delivery risk?", "options": ["Remove it because any boxplot flag establishes a recording error", "Use the large residual to prove the regression includes all relevant context", "Remove it because rare delays cannot matter to future risk", "Investigate and retain or appropriately represent the real risk rather than deleting it solely to improve fit"]}, {"id": "Q4-29", "topic": "M2", "type": "multi", "stem": "A min-max scaler is trained on values from 0 to 10. Which statements about future x=15 are correct?", "options": ["It lies outside the original training range", "Min-max fitting did not guarantee bounds for all future observations", "It must be silently clipped to one in every application", "Its transformed value is 1.5"]}, {"id": "Q4-30", "topic": "M3", "type": "multi", "stem": "Which statements about k-fold CV follow from its construction?", "options": ["Average scores can compare candidate settings", "Each fit excludes the held-out fold's outcomes from training", "Final deployment must use k different models even when no ensemble was intended", "Every fold is held out in turn"]}, {"id": "Q4-31", "topic": "M10", "type": "single", "stem": "A forest's importance chart ranks a predictor highly. A manager says increasing that predictor must increase the response by a fixed amount and cause an improvement. Which correction is most appropriate?", "options": ["A predictive model's importance ranking identifies the true physical causes", "Every high-importance predictor can be changed freely without constraints", "Importance is identical to a positive regression coefficient in original units", "Importance indicates predictive contribution under that fitted procedure; it need not give a signed linear effect or establish a causal intervention effect"]}, {"id": "Q4-32", "topic": "M9", "type": "multi", "stem": "Which statements about Box-Cox and regression assumptions are correct?", "options": ["Lambda is a transformation parameter", "Normality relevant to conventional regression inference concerns errors conditional on predictors", "A normal raw-response histogram guarantees equal conditional variance", "The standard Box-Cox family requires positive input values"]}, {"id": "Q4-33", "topic": "M2", "type": "multi", "stem": "A team changes income units from dollars to thousands of dollars. It keeps an unscaled k-NN distance rule otherwise unchanged and compares it with a tree using equivalent rescaled thresholds. Which statements are reasonable?", "options": ["An equivalent monotone rescaling preserves the ordering relevant to a tree threshold", "Both fitted procedures must change in exactly the same way", "The change can alter the relative weight of income in unscaled neighbor distances", "The transformation should be applied consistently to training and new observations"]}, {"id": "Q4-34", "topic": "M10", "type": "multi", "stem": "Which statements about ordinary trees and model trees are accurate?", "options": ["Leaf-specific regressions require enough observations to estimate coefficients", "A model tree can fit a separate regression within a leaf", "Ordinary regression CART often uses a constant leaf mean", "Every ordinary regression tree must fit every slope at each leaf"]}, {"id": "Q4-35", "topic": "M2", "type": "multi", "stem": "For overlapping training classes, which statements about soft-margin SVM are reasonable?", "options": ["Some violations can be accepted", "Class-specific loss multipliers can reflect asymmetric costs", "Violations are balanced against margin regularization", "The optimization must always become infeasible"]}, {"id": "Q4-36", "topic": "M3", "type": "single", "stem": "A dataset includes ordinary and holiday operations. A random split happens to place nearly all holiday cases in training, while the model will be deployed on both types. Which conclusion is supported?", "options": ["Using more predictors automatically supplies missing holiday evidence in validation", "The holiday cases should be deleted because they complicate the split", "The validation set may inadequately represent deployment, so its score should be interpreted with that coverage concern", "Any random split guarantees representative subgroups"]}, {"id": "Q4-37", "topic": "M7", "type": "single", "stem": "A forecast team has only a short, noisy demand history and asks whether an ARIMA model is automatically preferable to exponential smoothing because it is more general. Which response best reflects the survey lecture?", "options": ["More lag parameters make scarce observations irrelevant", "ARIMA must dominate smoothing on every series because it has more options", "GARCH supplies demand values whenever ARIMA lacks data", "Generality does not ensure a better forecast; data amount, behavior, and validation should guide the comparison"]}, {"id": "Q4-38", "topic": "M7", "type": "multi", "stem": "Which choices must be distinguished when specifying Holt-Winters?", "options": ["Cycle length in observations", "Additive versus multiplicative seasonal form", "Number of response categories as the seasonal parameter", "Observation frequency"]}, {"id": "Q4-39", "topic": "M10", "type": "single", "stem": "A call-center model predicts the number of arrivals in an interval from time of day and holiday status. Which introduced regression family naturally models this count mean?", "options": ["PCA without a response", "Poisson regression", "Hard-margin SVM", "Binary logistic regression only"]}, {"id": "Q4-40", "topic": "M10", "type": "multi", "stem": "Which conclusions are justified by ROC AUC=.9?", "options": ["The scores have strong positive-versus-negative ranking under the evaluation distribution", "It proves predicted probabilities are perfectly calibrated", "It specifies neither a deployment threshold nor its cost", "It means exactly 90% accuracy at every threshold"]}, {"id": "Q4-41", "topic": "M4", "type": "multi", "stem": "A k-means segmentation uses distance squared=4*(income difference squared)+(age difference squared) after representing both features on agreed scales. A manager calls the weights learned regression effects. Which statements are correct?", "options": ["The weights define similarity, not coefficients of a supervised response model", "The weight of four proves that changing income causes four times as much response change", "Increasing the income weight guarantees a more useful customer segmentation", "The stated weighting makes income differences contribute more to this distance than equal-sized age differences"]}, {"id": "Q4-42", "topic": "M2", "type": "multi", "stem": "Which statements about k-NN model behavior are correct?", "options": ["Its distance definition can change the selected neighbors", "It learns the same separating hyperplane as SVM by definition", "It stores/usefully retains labeled examples for prediction", "Increasing k may smooth local variation"]}, {"id": "Q4-43", "topic": "M8", "type": "single", "stem": "Two candidate models have similar fit on the same observations. BIC prefers the simpler one more strongly than AIC does. Which interpretation is defensible?", "options": ["BIC is a direct measure of classification accuracy", "The criteria use different complexity penalties; disagreement does not require a computation error", "The simpler model is proved to be the causal truth", "AIC and BIC must always rank models identically"]}, {"id": "Q4-44", "topic": "M7", "type": "multi", "stem": "A team has 12 historical observations but wants an ARIMA specification with many value and error lags. It treats the lecture's approximate 40-observation guidance as an absolute law. Which statements are appropriate?", "options": ["Reaching 40 observations guarantees the model and chosen lag orders are adequate", "A simpler model and realistic validation may be sensible alternatives", "The guidance is a rule of thumb rather than a universal guarantee or prohibition", "The very short history and flexible specification raise a legitimate estimation and overfitting concern"]}, {"id": "Q4-45", "topic": "M4", "type": "single", "stem": "A cluster-based service plan assigns a remote new demand point to the least-distant existing center. The manager concludes the current facility can serve it within the required response time. What is the best correction?", "options": ["Nearest-center assignment guarantees compliance with every operational constraint", "Nearest among existing centers does not imply close enough for the service standard; coverage must be evaluated separately", "A cluster ID directly supplies the travel time without a travel model or measurement", "The assignment proves that the new point was part of the training data"]}, {"id": "Q4-46", "topic": "M4", "type": "tf", "stem": "Permuting the names of clusters changes WSS when centers and memberships stay the same.", "options": []}, {"id": "Q4-47", "topic": "M6", "type": "blank", "stem": "For upper CUSUM with previous statistic=0, observation=18, baseline=12, and allowance=2, the new statistic is ____.", "options": []}, {"id": "Q4-48", "topic": "M7", "type": "tf", "stem": "A seasonal multiplicative factor below one necessarily reveals why that seasonal pattern occurs.", "options": []}, {"id": "Q4-49", "topic": "M9", "type": "blank", "stem": "If PCA eigenvalues are 5,3,2, the first component's predictor-variance fraction is ____.", "options": []}, {"id": "Q4-50", "topic": "M10", "type": "blank", "stem": "With TP=20,FN=5,FP=15,TN=60, specificity equals ____.", "options": []}], [{"id": "Q5-01", "topic": "M9", "type": "multi", "stem": "A team clusters unlabeled customers and also fits a repayment classifier using known outcomes. It proposes using PCA learned on the full dataset before evaluating either procedure. Which statements distinguish the tasks and evaluation issue?", "options": ["A learned PCA representation intended for predictive evaluation should be fitted within the training procedure", "Clustering discovers feature-based groups, while classification learns from outcome labels", "Cluster names are automatically repayment labels", "The absence of response labels in PCA means it cannot affect the evaluation pipeline"]}, {"id": "Q5-02", "topic": "M5", "type": "multi", "stem": "A verified demand spike came from a unique publicity event. A team wants forecasts for ordinary weeks, while another team wants emergency capacity planning that includes rare surges. Which handling is defensible?", "options": ["The ordinary-week model's error cannot be presented as performance for all weeks without qualification", "Its removal can be justified only by checking validity and target relevance, not by a better fitted score alone", "Every rare event should be deleted from both analyses", "The event's relevance can differ between the two target questions"]}, {"id": "Q5-03", "topic": "M5", "type": "multi", "stem": "Which questions should precede outlier handling?", "options": ["Which deletion maximizes training R-squared regardless of reality?", "What generated its unusual value?", "Is the record valid?", "Must the intended predictions or decisions cover that circumstance?"]}, {"id": "Q5-04", "topic": "M8", "type": "single", "stem": "A regression with many fitted parameters looks excellent on a small dataset. A corrected information criterion penalizes it more than uncorrected AIC. Which interpretation is appropriate?", "options": ["The correction supplies new observations that were not collected", "The lower training error alone proves the corrected criterion is wrong", "The correction addresses the finite-data situation and can discourage over-complex fitting", "A complexity criterion removes all need for validation or checking model assumptions"]}, {"id": "Q5-05", "topic": "M4", "type": "multi", "stem": "A hospital groups patient pickup locations with k-means to propose transport hubs. Some routes require crossing a river at a bridge. It then uses a classifier to predict whether each patient needs urgent pickup. Which statements separate the roles correctly?", "options": ["The classifier needs known urgency outcomes or labels for training", "The cluster with the largest coordinate values must be the urgent class", "Clustering can suggest geographic groups, but route constraints still matter to hub placement", "Distance-based grouping by itself proves which patients are medically urgent"]}, {"id": "Q5-06", "topic": "M4", "type": "multi", "stem": "Which statements about a cluster-based facility plan are correct?", "options": ["The number of facilities can constrain k", "Minimum WSS automatically satisfies every operational constraint", "A center is an analytical candidate, not automatically a feasible building site", "Coverage and travel constraints may require additional analysis"]}, {"id": "Q5-07", "topic": "M10", "type": "single", "stem": "A regression tree considers a split into a two-case child and an eighteen-case child. The two-case child has no training variation, and total training error falls slightly. Which reasoning best follows the lecture?", "options": ["Any split reducing training error must be retained", "Both children count equally regardless of size when measuring the total fit", "The zero variation in two cases proves the new leaf will generalize perfectly", "Assess improvement and adequate child support, then validate or prune; the tiny perfect leaf is not sufficient evidence of usefulness"]}, {"id": "Q5-08", "topic": "M7", "type": "multi", "stem": "Reliability is measured as operating hours before failure for each successive manufactured item; production batches contain 150 items. Which interpretations are supported?", "options": ["A seasonal factor .7 at a phase represents a lower proportional response", "Cycle length can be 150 observations", "A positive trend proves the training policy caused improvement", "A positive trend means modeled reliability response rises over successive items"]}, {"id": "Q5-09", "topic": "M9", "type": "multi", "stem": "Two standardized predictor columns are exact duplicates. PCA is used before regression. Which statements are reasonable?", "options": ["Duplicated predictors establish two independent causal effects", "Keeping the first component can summarize the shared predictor information", "The second direction has no additional variation beyond the first", "The first component therefore guarantees a perfect response prediction"]}, {"id": "Q5-10", "topic": "M3", "type": "single", "stem": "Eight-fold validation on 1,600 non-test observations selects a regression specification. The final test set has not been used. Which fitting plan reflects the lecture approach?", "options": ["Refit the chosen specification on all 1,600 non-test observations and then evaluate once on the untouched test set", "Average fold coefficients automatically because cross-validation requires that final estimator", "Fit the final model on only the 200 observations from the best validation fold", "Use the final test responses to select a different predictor subset before reporting the same test score"]}, {"id": "Q5-11", "topic": "M1", "type": "multi", "stem": "Which features make a modeling conclusion useful and defensible?", "options": ["Its limitations and assumptions are understood", "It answers the actual operational question", "It respects the information and population represented by the data", "It agrees with the analyst's initial belief regardless of the evidence"]}, {"id": "Q5-12", "topic": "M3", "type": "multi", "stem": "The team compares SVM, k-NN, and a tree on a training/validation split. Before splitting, it selects features by checking their relationships with all response labels. Which statements identify the concern?", "options": ["The validation outcomes influenced feature selection", "Using several model families does not repair that leakage", "Every later validation score is guaranteed to be an unbiased final estimate because coefficients were fitted only on training cases", "Feature selection should be part of the training and validation procedure rather than use the held-out labels beforehand"]}, {"id": "Q5-13", "topic": "M7", "type": "single", "stem": "A volatility model reports high variance after a quiet latest observation because earlier volatility was high. A manager says zero latest signed error must force zero variance. Which correction fits GARCH's lecture-level mechanism?", "options": ["Every positive variance implies the next return is positive", "Lagged variance as well as squared errors can carry volatility forward; a quiet new observation need not erase it", "GARCH obtains changing variance by differencing the variance exactly like ARIMA differences observations", "Variance depends only on the sign of the latest error"]}, {"id": "Q5-14", "topic": "M7", "type": "single", "stem": "A multiplicative seasonal factor is estimated at 1.2 for the current phase of a production cycle. The team instead proposes an additive seasonal term of +1.2 in the same response units without refitting. Which statement is correct?", "options": ["The two quantities mean different things: a multiplicative factor rescales the baseline, while an additive effect is an amount on the response scale", "Both always produce the same forecast for any baseline", "A factor above one proves the cause of the seasonal effect", "The factor says every observation in that phase equals exactly 1.2"]}, {"id": "Q5-15", "topic": "M7", "type": "multi", "stem": "Monthly output increases roughly linearly, while its first differences appear much more stable. A team proposes differencing and then an ARIMA model; another proposes a trend component in smoothing. Which conclusions are defensible?", "options": ["The stable first differences prove the physical cause of the growth", "The resulting candidate forecasts should be compared rather than declaring one universally best", "Increasing ARIMA d always improves the forecast without changing interpretation", "Differencing and explicit trend smoothing are different ways of representing temporal structure"]}, {"id": "Q5-16", "topic": "M4", "type": "multi", "stem": "At the same k, two k-means starts produce WSS=90 and WSS=100. For a larger k, another run produces WSS=60. Which comparisons are justified?", "options": ["Different starts can lead to different local solutions", "The larger-k run's lower WSS alone proves it is the best operational segmentation", "The minimum observed raw WSS automatically identifies the most useful k for deployment", "At the same k, the lower-WSS run is better under the stated training objective"]}, {"id": "Q5-17", "topic": "M10", "type": "single", "stem": "A calibrated probability model predicts p for a rare fault. False alarms cost $3, missed faults cost $9, and correct actions cost zero. At p=.30, which action has lower stated expected error cost?", "options": ["Declare no fault because .30 is below .50, regardless of consequences", "The choice is impossible because a probability cannot inform a decision", "Declare a fault: expected cost .70*3=$2.10 is less than .30*9=$2.70", "The actions must have the same expected cost because both use the same probability"]}, {"id": "Q5-18", "topic": "M2", "type": "single", "stem": "Two candidate neighbor rules have validation costs $12 and $8 per 100 decisions despite accuracies .95 and .90 respectively. If minimizing this measured cost is the objective, which is favored?", "options": ["The .90-accuracy rule with $8 cost", "The rule with more neighbors regardless of validation", "The .95-accuracy rule regardless of cost", "Neither because only accuracy is legal as a metric"]}, {"id": "Q5-19", "topic": "M7", "type": "multi", "stem": "A manufacturer records item position, production day, and operating hours before failure across fixed 150-item batches. Item position and production day are highly correlated. It wants to examine early-batch reliability. Which statements align the time-series and PCA roles?", "options": ["PCA of the two correlated predictors can summarize their shared variation before a factor-based regression", "PCA by itself determines why early items fail", "The batch's calendar duration replaces 150 even when the series advances once per item", "An item-indexed seasonal model uses reliability hours as the response and 150 as the cycle length"]}, {"id": "Q5-20", "topic": "M6", "type": "single", "stem": "An upper CUSUM starts at zero with baseline 10 and allowance 1. Three readings of 12 arrive. The threshold is 2 and the alarm rule is S>2. Which interpretation is correct?", "options": ["The alarm must occur on the first reading because 12 exceeds the baseline", "The statistics are 1, 2, and 3; the first alarm occurs on the third reading under this rule", "Each reading is tested independently, so accumulation has no effect", "The third reading proves a particular operator caused the change"]}, {"id": "Q5-21", "topic": "M9", "type": "multi", "stem": "An analyst has many correlated numerical measurements and proposes keeping a few leading PCA components before fitting a predictive model. Which statements fit the survey-level purpose and limits?", "options": ["PCA guarantees that no predictive information is lost whenever most predictor variance is retained", "The downstream model should be evaluated because PCA did not use the response to define its directions", "PCA itself chooses retained components by their relationship with the observed response labels", "PCA can reduce the number of coordinates while preserving much of the measured predictor variation"]}, {"id": "Q5-22", "topic": "M7", "type": "multi", "stem": "A response is usually positive but sometimes zero. The team plans multiplicative Holt-Winters updates that divide by a seasonal factor and current level. Which choices are defensible?", "options": ["Assume naming the method seasonal makes zero-related numerical issues impossible", "Treat multiplication and addition as interchangeable without changing the updates", "Consider whether a different seasonal representation better matches the response behavior", "Check whether the model's divisions and scale assumptions are suitable for these observations"]}, {"id": "Q5-23", "topic": "M10", "type": "multi", "stem": "A random forest outperforms one tree on validation, but both models were trained with a predictor recorded after the decision deadline. Which conclusions follow?", "options": ["Tree diversity does not repair unavailable-predictor leakage", "The forest's higher validation score establishes that it can be deployed at the stated decision time", "The candidate pipeline must be revised and reassessed using timely predictors", "Enough trees automatically create the missing pre-decision information"]}, {"id": "Q5-24", "topic": "M9", "type": "multi", "stem": "Which statements correctly contrast feature selection and feature extraction?", "options": ["Extraction can reduce dimension without selecting original columns directly", "PCA always chooses exactly one original variable as its first component", "Selection retains a subset of original variables", "PCA extraction constructs linear combinations"]}, {"id": "Q5-25", "topic": "M2", "type": "multi", "stem": "A clinic has binary infection labels and symptoms available at screening. It wants probabilities for risk communication, class decisions for triage, and an alarm if average symptom severity shifts over time. Which statements assign roles correctly?", "options": ["Logistic regression directly addresses infection probability from symptoms", "A class decision can use a chosen threshold on that probability", "CUSUM of ordered symptom measurements addresses the shift-detection request", "Clustering symptom measurements automatically gives calibrated infection probabilities without infection labels"]}, {"id": "Q5-26", "topic": "M7", "type": "multi", "stem": "Which contrasts between time-series methods are correct?", "options": ["Simple smoothing extrapolates a level without explicit trend", "Holt-Winters adds a repeating seasonal component", "GARCH's primary output is a list of unsupervised customer clusters", "Holt adds an evolving trend"]}, {"id": "Q5-27", "topic": "M2", "type": "single", "stem": "A linear classifier predicts positive for x1+x2>6. A case moves from (2,3) to (2,5). A manager attributes the resulting class change to a causal effect of increasing x2. Which interpretation is correct?", "options": ["Changing coordinates proves that all other conditions in the system stayed fixed", "The predicted class changes because the case crosses the rule, but that mathematical change is not proof of a causal effect in the real system", "The class cannot change because only one predictor moved", "The boundary gives a 100% probability of the positive event after the move"]}, {"id": "Q5-28", "topic": "M8", "type": "single", "stem": "A production regression finds an apparently useful negative association between speed and reliability. Its interval is wide and includes zero, and speed is correlated with batch conditions. Which reporting approach is defensible?", "options": ["Report the estimated direction and uncertainty, and avoid a causal recommendation unsupported by the design", "Treat the fitted negative coefficient as certain for every future batch", "Ignore the predictor correlation because the coefficient has a sign", "Report that speed has exactly no relationship because zero is in the interval"]}, {"id": "Q5-29", "topic": "M10", "type": "multi", "stem": "If class prevalence changes but sensitivity and specificity stay fixed, which metrics generally can change?", "options": ["Overall accuracy", "Precision", "Expected cost per observation", "Sensitivity by assumption"]}, {"id": "Q5-30", "topic": "M6", "type": "multi", "stem": "A safety monitor is retuned to alarm with less accumulated evidence. Missed developing faults are especially costly, but false alarms interrupt production. Which statements describe the tradeoff?", "options": ["The retuning guarantees no missed faults and no false alarms", "The threshold should be evaluated against both consequences", "A lower threshold can detect shifts sooner", "A lower threshold can also increase false alarms"]}, {"id": "Q5-31", "topic": "M7", "type": "multi", "stem": "A forecast model has an estimated rising trend, but a control engineer needs to flag a sudden increase relative to a stable reference. Which statements correctly separate the two goals?", "options": ["CUSUM directly accumulates evidence relative to the stated reference", "A positive fitted trend automatically identifies a sudden change date and its cause", "Holt can model level plus an evolving trend for forecasting", "The engineer should choose a baseline meaningful for the monitoring task rather than treating a forecasting output as the same decision"]}, {"id": "Q5-32", "topic": "M2", "type": "multi", "stem": "Which are distinct choices in a k-NN classification specification?", "options": ["Distance metric", "Number of lagged innovations as a required k-NN parameter", "Number of neighbors", "Feature scaling/weights"]}, {"id": "Q5-33", "topic": "M10", "type": "multi", "stem": "A cancer-screening classifier evaluates 1,000 people and produces TP=8, FN=2, FP=90, TN=900. Which statements are correct?", "options": ["The rare positive class makes accuracy alone an incomplete summary for this screening task", "The high accuracy makes the cost of missed cancers and follow-up tests irrelevant", "Accuracy is (8+900)/1000=.908", "Among positive predictions, 8/98 actually have cancer"]}, {"id": "Q5-34", "topic": "M10", "type": "multi", "stem": "A clinic expects disease prevalence .20. A model has sensitivity .75 and specificity .90. Missing disease costs $20, an unnecessary follow-up costs $1, and correct decisions are free. Which statements correctly translate this into expected error cost?", "options": ["Prevalence, both class-conditional error rates, and costs are needed for this population comparison", "The population false-negative fraction is .20*(1-.75)=.05", "The expected error cost per person is .05*20+.08*1=$1.08", "The population false-positive fraction is .80*(1-.90)=.08"]}, {"id": "Q5-35", "topic": "M8", "type": "multi", "stem": "Which can explain a correlation without a direct causal effect of x on y?", "options": ["A small p-value necessarily eliminates all alternatives", "Reverse causation", "Selection or omitted-variable structure", "A common cause affects both"]}, {"id": "Q5-36", "topic": "M1", "type": "multi", "stem": "A restaurant estimates arrival counts from time of day and holiday status, groups menu demand patterns, and decides purchase quantities under spoilage costs. Which statements assign methods or roles appropriately?", "options": ["The count forecast alone specifies the optimal purchase quantities under all costs", "K-means can group feature profiles without a labeled outcome", "Purchase decisions require the operational objective in addition to the predictive inputs", "Poisson regression can model an attribute-dependent arrival count rate"]}, {"id": "Q5-37", "topic": "M3", "type": "multi", "stem": "Why can a single holdout estimate vary materially across random splits?", "options": ["Each fit may change when its training subset changes", "Different splits allocate rare or influential cases differently", "Finite validation sets contain random variation", "The method eliminates all sources of randomness by definition"]}, {"id": "Q5-38", "topic": "M10", "type": "multi", "stem": "Four teams need a count rate from attributes, a smoothly varying numeric response, updated coefficient beliefs with few observations, and a numeric prediction from similar labeled records. Which pairings match the introduced methods?", "options": ["Regression splines can join polynomial pieces with smooth connections", "Poisson regression can address the attribute-dependent count rate", "k-NN regression averages nearby numeric responses without requiring one global straight-line equation", "Bayesian regression can combine starting coefficient distributions with observed data"]}, {"id": "Q5-39", "topic": "M2", "type": "multi", "stem": "A trained model is sensitive to a unit change from dollars to thousands of dollars. Which explanations can be relevant?", "options": ["An unadjusted distance metric changes its numerical geometry", "An unadjusted norm penalty can change its relative feature treatment", "Every algorithm is invariant to arbitrary feature units without any adjustment", "Consistent preprocessing can address the scale change"]}, {"id": "Q5-40", "topic": "M6", "type": "multi", "stem": "Which choices could reasonably improve the interpretation of a CUSUM study?", "options": ["Check sensitivity to plausible C and T values", "Treat one local alarm as proof of an unrelated national policy effect", "Report a narrow conclusion matching the measured outcome", "Use a baseline appropriate to the unchanged regime"]}, {"id": "Q5-41", "topic": "M8", "type": "multi", "stem": "A team models log(cost) instead of cost to improve a regression's behavior. The manager interprets an added unit of the transformed-response prediction as an added dollar of expected cost. Which concerns are warranted?", "options": ["The transformed response and raw-dollar response have different scales", "A transformation automatically proves the original response was measured incorrectly", "Predictive performance should be judged on a scale relevant to the application, not mislabeled units", "Reporting should explain how the fitted predictions relate to the original units"]}, {"id": "Q5-42", "topic": "M3", "type": "multi", "stem": "Which claims about a final test score are appropriate?", "options": ["It may fail to represent deployment after a substantial distribution shift", "It still has finite-sample uncertainty", "It estimates performance under the test sampling conditions", "It guarantees identical accuracy in every future population"]}, {"id": "Q5-43", "topic": "M4", "type": "multi", "stem": "Which interpretations of a large optimal WSS decrease are defensible?", "options": ["Adding a cluster improves feature-space fit", "The new group may merit substantive investigation", "Operational relevance can differ from mathematical improvement", "The result alone establishes a known response-category boundary"]}, {"id": "Q5-44", "topic": "M2", "type": "multi", "stem": "A clinic has labeled symptom records and needs an infection-positive or infection-negative class prediction for new patients. Which lecture approaches can be used for this classification task?", "options": ["k-means interpreted as a supervised classifier by definition", "Classification trees", "k-NN classification", "SVM"]}, {"id": "Q5-45", "topic": "M8", "type": "single", "stem": "A model with lower AIC predicts slightly worse on representative held-out cases than an alternative. Management's goal is the held-out decision cost, and the lower-AIC model also has higher cost. Which conclusion is defensible?", "options": ["Lower AIC guarantees lower cost for every decision rule", "The held-out comparison must be wrong whenever it disagrees with AIC", "AIC identifies the action with the largest business profit without an action model", "AIC is useful model-comparison evidence, but it does not override the stated operational objective and appropriate validation evidence"]}, {"id": "Q5-46", "topic": "M1", "type": "tf", "stem": "A model family, a predictor specification, and a fitted numerical equation can all be called a model in these lectures.", "options": []}, {"id": "Q5-47", "topic": "M2", "type": "blank", "stem": "Two soft-margin SVM settings fit training data differently. To select the setting for prediction, compare their ____ performance rather than training fit alone.", "options": []}, {"id": "Q5-48", "topic": "M5", "type": "tf", "stem": "A collective outlier must contain at least one individual value that is extreme without any context.", "options": []}, {"id": "Q5-49", "topic": "M7", "type": "blank", "stem": "ARIMA(p,d,q) uses p for ____ lags and q for ____ lags.", "options": []}, {"id": "Q5-50", "topic": "M10", "type": "blank", "stem": "A standard constant-response regression-tree leaf predicts the ____ of its training responses, whereas a classification leaf usually predicts the most common class.", "options": []}]];
